// #6a993d767a46a91b6fdf30ff — פיתוח: הגדרת מידע הלקוח המדומה ומדרג החשיפה שלו (F-12, S-08 шаг 2). Кейсы SIM-101…SIM-104.
// Роль: business (testim), сохранённая сессия, без пароля. Десктоп 1440×900.
// Данные: два черновика «QA-AUTO-df30ff-<stamp>» и «QA-AUTO-df30ff-<stamp>-ריק» (טיוטה, неудаляемы).
// Ничего не утверждается и не активируется; генерация AI на /draft подменяется ответом 422 (AI не вызывается).
// Не автоматизировано: экраны кандидата / ответ candidate_open_link (нужна активная симуляция и кандидат — активация запрещена).
import { test, expect } from '@playwright/test';
import { openWithApi, runStamp } from '../support/api';
import { field, currentStep, createDraftViaStep1, nextStep, simById, blockScenarioGeneration, GENERAL } from '../support/simulation-editor';

test.use({ storageState: '../auth/business.json' });
test.describe.configure({ mode: 'serial' });

const STAMP = runStamp();
const DRAFT_NAME = `QA-AUTO-df30ff-${STAMP}`;
const EMPTY_NAME = `QA-AUTO-df30ff-${STAMP}-ריק`;
const TAG = '#6a993d767a46a91b6fdf30ff';
const ITEM_UPFRONT = `QA-AUTO גלוי: בעל בית פרטי ברמת גן ${STAMP}`;
const ITEM_DISCOVER = `QA-AUTO לגלות: חשבון החשמל כ-900 ש״ח לחודש ${STAMP}`;
const ITEM_QUESTION = `QA-AUTO בשאלה: תקציב עד 40 אלף ש״ח ${STAMP}`;
const CONDITION = 'כשהמועמד שואל על תקציב או מסגרת מחיר';
const NO_CONDITION = 'חסר תנאי: איזו שאלה חושפת את המידע?';
let draftId = '';

const tierGroup = (page: import('@playwright/test').Page, n: number) =>
  page.getByRole('group', { name: new RegExp(`^רמת החשיפה של פריט מידע ${n}:`) });
const preview = (page: import('@playwright/test').Page) => page.getByTestId('candidate-preview-panel');

test.describe(`Редактор симуляции — шаг 2 «לקוח וחשיפה» (${TAG})`, () => {
  test(`шаг 2 без пунктов «מוצג מראש»: предупреждение «המועמד יגיע לשיחה בלי שום הקשר» @desktop @data ${TAG}`, async ({ page }) => {
    const saved = await createDraftViaStep1(page, DRAFT_NAME);
    draftId = saved.id;
    test.info().annotations.push({ type: 'test-data', description: `simulation ${DRAFT_NAME} ${draftId} (draft, неудаляем)` });

    await expect(page.getByText('עדיין לא נוספו פריטי מידע.')).toBeVisible();
    // Источник: «מה רצוי» R2 — предупреждение, если нет ни одного пункта «מוצג מראש».
    const warning = page.getByTestId('no-upfront-warning');
    await expect(warning).toContainText('עדיין אין מידע שמוצג למועמד מראש, ולכן המועמד יגיע לשיחה בלי שום הקשר.');
    await expect(warning).toContainText('כדאי לסמן לפחות פריט אחד כ«מוצג מראש»');
  });

  test(`3 уровня раскрытия; «רק בשאלה» без условия закрывает переход; у «לגלות בשיחה» поля условия нет; предпросмотр — только «מוצג מראש» @desktop @data ${TAG}`, async ({ page }) => {
    expect(draftId, 'нужен черновик из предыдущего теста (serial)').toBeTruthy();
    await page.goto(`/simulations/${draftId}?step=customer`);
    await expect(currentStep(page, 'customer')).toBeVisible();

    await field(page, 'customer_opening_state').fill('QA-AUTO סקפטי ועסוק, עונה בקצרה');
    await field(page, 'customer_need').fill('QA-AUTO חשבון חשמל גבוה בקיץ');
    await expect(field(page, 'prior_relationship')).toHaveValue(''); // AC5: не обязательно — оставляем пустым

    const add = page.getByRole('button', { name: 'הוספת פריט מידע' });
    for (const [n, text, tier] of [
      [1, ITEM_UPFRONT, 'מוצג מראש'],
      [2, ITEM_DISCOVER, 'לגלות בשיחה'],
      [3, ITEM_QUESTION, 'רק בשאלה'],
    ] as const) {
      await add.click();
      await field(page, `info_items.${n - 1}.text`).fill(text);
      const group = tierGroup(page, n);
      // AC1: у каждого пункта переключатель из 3 вариантов.
      await expect(group.getByRole('radio')).toHaveCount(3);
      await group.getByText(tier, { exact: true }).click();
      await expect(group.getByRole('radio', { name: tier })).toBeChecked();
    }

    // AC2: условие есть только у «רק בשאלה»; у «לגלות בשיחה» поля условия нет.
    await expect(field(page, 'info_items.1.reveal_condition')).toHaveCount(0);
    await expect(field(page, 'info_items.2.reveal_condition')).toBeVisible();

    // AC4: «מה המועמד יראה לפני השיחה» — только пункт «מוצג מראש», 2 скрыты.
    await expect(preview(page)).toContainText(ITEM_UPFRONT);
    await expect(preview(page)).not.toContainText(ITEM_DISCOVER);
    await expect(preview(page)).not.toContainText(ITEM_QUESTION);
    await expect(preview(page)).toContainText('2 פריטים מוסתרים — ייחשפו רק בשיחה');
    await expect(page.getByTestId('no-upfront-warning')).toHaveCount(0);

    // AC2: без условия переход на шаг 3 закрыт.
    let saveCalls = 0;
    page.on('request', (r) => { if (r.url().includes('/rpc/save_simulation')) saveCalls += 1; });
    await page.getByRole('button', { name: 'הבא: התנגדות' }).click();
    await expect(page.getByText(/אי אפשר לעבור לשלב 3 — (דבר אחד חסר|\d+ דברים חסרים)/)).toBeVisible();
    await expect(page.locator('#simulation-info_items-2-reveal_condition-error')).toHaveText(NO_CONDITION);
    await expect(field(page, 'info_items.2.reveal_condition')).toHaveAttribute('aria-invalid', 'true');
    await expect(currentStep(page, 'customer')).toBeVisible();
    await expect(field(page, 'info_items.0.text')).toHaveValue(ITEM_UPFRONT);
    expect(saveCalls).toBe(0);

    // С условием — сохраняется: «לגלות בשיחה» → reveal_condition:null, пустой «קשר קודם» не мешает (AC5).
    await field(page, 'info_items.2.reveal_condition').fill(CONDITION);
    const res = await nextStep(page, 'התנגדות');
    expect(res.status(), await res.text()).toBe(200);
    const sent = res.request().postDataJSON() as { p_fields: { info_items: { text: string; tier: string; reveal_condition: string | null }[] } };
    expect(sent.p_fields.info_items).toEqual([
      { text: ITEM_UPFRONT, tier: 'shown_upfront', reveal_condition: null },
      { text: ITEM_DISCOVER, tier: 'discover_in_call', reveal_condition: null },
      { text: ITEM_QUESTION, tier: 'on_question', reveal_condition: CONDITION },
    ]);
    await expect(currentStep(page, 'objection')).toBeVisible();

    const api = await openWithApi(page, `/simulations/${draftId}`);
    const row = await simById(api, draftId);
    expect(row.prior_relationship ?? '').toBe('');
    expect(row.info_items).toEqual(sent.p_fields.info_items);
  });

  test(`«סקירת הטיוטה»: в «מה המועמד יראה» и в get_candidate_view нет скрытых пунктов @desktop @data ${TAG}`, async ({ page }) => {
    expect(draftId, 'нужен черновик из предыдущего теста (serial)').toBeTruthy();
    await blockScenarioGeneration(page);
    const view = page.waitForResponse((r) => r.url().includes('/rpc/get_candidate_view'));
    await page.goto(`/simulations/${draftId}/draft`);
    const body = await (await view).text();
    // Треб.5 / AC4: скрытое не уходит в данные кандидата.
    expect(body).toContain(ITEM_UPFRONT);
    expect(body).not.toContain(ITEM_DISCOVER);
    expect(body).not.toContain(ITEM_QUESTION);
    expect(body).not.toContain(CONDITION);

    const panel = page.getByRole('region', { name: 'מה המועמד יראה' });
    await expect(panel).toContainText(ITEM_UPFRONT);
    await expect(panel).not.toContainText(ITEM_DISCOVER);
    await expect(panel).not.toContainText(ITEM_QUESTION);
  });

  test(`передача на утверждение без «מצב הלקוח» и «הצורך»: 400 missing_required_fields и список полей-ссылок @desktop @data ${TAG}`, async ({ page }) => {
    await blockScenarioGeneration(page);
    const api = await openWithApi(page, '/simulations');
    // Черновик только с шагом 1 (те же поля, что и в UI); шаг 2 пуст.
    const created = await api.rpc('save_simulation', {
      p_simulation_id: null,
      p_fields: { name: EMPTY_NAME, ...GENERAL, language: 'he', duration_minutes: 7, desired_next_step: 'consultation_meeting', end_conditions: null },
    });
    expect(created.status(), await created.text()).toBe(200);
    const { id } = (await created.json()) as { id: string };
    test.info().annotations.push({ type: 'test-data', description: `simulation ${EMPTY_NAME} ${id} (draft, неудаляем)` });

    await page.goto(`/simulations/${id}/draft`);
    const submit = page.waitForResponse((r) => r.url().includes('/rpc/submit_simulation_for_approval'));
    await page.getByTestId('submit-for-approval').click();
    const res = await submit;
    // AC3 / треб.7: утверждение закрыто, недостающие поля названы конкретно.
    expect(res.status()).toBe(400);
    expect(await res.text()).toContain('missing_required_fields');

    const box = page.getByTestId('missing-fields');
    await expect(box).toContainText('האישור נחסם: חסרים שדות חובה');
    const opening = box.getByRole('link', { name: 'מצב הלקוח בתחילת השיחה' });
    const need = box.getByRole('link', { name: 'הצורך או הבעיה של הלקוח' });
    await expect(opening).toHaveAttribute('href', `/simulations/${id}?step=customer&field=customer_opening_state`);
    await expect(need).toHaveAttribute('href', `/simulations/${id}?step=customer&field=customer_need`);
    await expect(box.getByRole('link', { name: /קשר קודם/ })).toHaveCount(0); // AC5: «קשר קודם» не обязателен

    expect((await simById(api, id)).status).toBe('draft');
  });
});
